"""Build a multi-resolution ICO from the PNG iconset generated by desktop/make-icon.swift.

Uses only the Python standard library. The retained SVG is the source of truth.
"""
import argparse
from pathlib import Path
import struct


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("iconset", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    files = [(16, "icon_16x16.png"), (32, "icon_32x32.png"),
             (64, "icon_32x32@2x.png"), (128, "icon_128x128.png"),
             (256, "icon_128x128@2x.png")]
    images = [(size, (args.iconset / name).read_bytes()) for size, name in files]
    offset = 6 + 16 * len(images)
    parts = [struct.pack("<HHH", 0, 1, len(images))]
    for size, data in images:
        if not data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise ValueError("Expected PNG image")
        parts.append(struct.pack("<BBBBHHII", size % 256, size % 256, 0, 0,
                                 1, 32, len(data), offset))
        offset += len(data)
    parts.extend(data for _, data in images)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_bytes(b"".join(parts))


if __name__ == "__main__":
    main()
